example:
static int Ration(int days)
{
    if (days < 1)
    {
        throw new InvalidOperationException("no days");
    }

    return 30 / days;
}

static string Plan(int days)
{
    string report = "ready";

    try
    {
        Ration(days);
    }
    catch (InvalidOperationException)
    {
        report = "no rations";
    }

    return report;
}
